                            "은명|너희들은 내 이름을 알 자격도, 물을 자격도 없다! 그 죄, 죽음으로 속죄하라!",
                            "독고령|무서웠어요, 엉엉……. 무서웠어요. 정말, 정말……. 무서웠어요…….",
