                            "독고령|가, 가까이 오지 말아요. ……은명! 왜? 어째서…….",
                            "은명|이것이 나의……, 숙명이기 때문이오.",
                            "독고령|비겁해요, 당신은 너무 비겁해요. 나의 눈이 필요하다면서, 왜 그런 죽을 듯 쓸쓸한 표정을 짓는 거냐고요!",
