                            "교옥|어머, 비 공자! 안녕하세요! 처음 뵙겠습니다, 저는 마천각 소속의 교옥이라고 합니다.",
                            "비류연|아! 누구신가 했더니 전에 저에게 예고도 없이 108개의 바늘을 뿌린 그 무례한 아가씨로군요.",
                            "교옥|아하하하하! 그건 오해에요, 오해! 사고였어요, 사고! ……저도 이제부터 같은 7조가 되었거든요! 앞으로 잘 부탁드려요!",
