            { 17, new[] {
                    "비류연이 마하령을 앞으로 내세우자 팽혁성의 칼이 억지로 궤도를 틀었다.",
                    "팽혁성|이게 무슨 돼먹지 못한 짓이냐? 여성을 방패로 삼다니? 네놈은 강호의 도의도 모르는 놈이었더냐?",
                    "비류연|어차피 안 맞게 할 거잖아요. 남녀는 평등한 거 아닌가요? 그리고 부하의 실수는 윗사람이 책임지는 게 당연하잖아요!",
                    "마하령|너…… 본녀가 누군지 진정으로 알고 이러는 것이냐? 너는 나에게 무릎을 꿇고 이마를 바닥에 찧으며 백배사죄하게 될 것이다.",
                    "비류연|하! 꿈도 야무지시네요. 당신이 설혹 황제의 딸이라 해도, 당신이 나에게 사과해야 한다는 사실에는 변함이 없다는 겁니다.",
                    "마하령|기억하마! 비류연! 반드시…… 기필코…… 네놈에게 이 세상에서 가장 끔찍한 지옥을 경험하게 해 주마.",
                    "비류연|해 보시죠, 뚱땡이 소저!",
                    "비류연|이제 그만 고집부리는 게 어때요? 전 단순한 사과를 원했을 뿐이에요.",
                    "마하령|누가 네놈에게 굴복할 성싶으냐? 나한텐 같은 의미다.",
                    "그때 군중이 갈라지며 한 사내가 걸어 나왔다.",
                    "용천명|이제 그만하는 게 어떤가? 본인은 미력하나마 구정회의 현 회주를 맡고 있는 소림의 용천명이라 하네!",
                } },
            { 18, new[] {
                    "무영무흔비월인 쌍월이 서로 다른 궤도로 날았다. 그 사이를 파고든 주먹이 빙검을 쓰러뜨렸다.",
                    "비류연|깨어났어요? 자, 그럼 이제 약속을 이행해야죠. 설마 무림의 명망 높으신 빙검 노사께서 어린 저에게 말을 번복하는 추태를 보이시지는 않겠죠?",
                    "비류연|첫 번째 조건은 바로 빙검 노사께서 저의 제자가 되는 것이죠. 쉽죠?",
                    "빙검|터무니없는 소리! 나이 적은 이를 사숙이라 부를 수는 있어도 사부라고 부를 수는 없다. 여태껏 그런 선례가 없지 않았소?",
                    "비류연|선례가 없다구요? 선례는 있죠. 원하시면 지금 당장 보여 드릴 수도 있습니다.",
                    "빙검|좋네! 증거를 보여 준다면 내 자네를 앞으로 영원토록 사부로 모시겠네.",
                    "비류연|남아일언!",
                    "빙검|중천금!",
                    "비류연|하하하하! 좋습니다. 염도!",
                    "염도|부르셨습니까, 사부님!",
                    "비류연|하하하하! 좋겠네요, 염도. 이제 사제가 들어왔으니 더욱더 노력해야겠네요.",
                    "염도|물론입니다, 사부님! 아주 확실히 교육시켜 놓겠습니다.",
                    "첫 번째 부탁은 그렇게 쓰였다. 남은 두 가지는 나중에 받기로 했다.",
                } },
            { 19, new[] {
                    "비류연|직접 시험해 보시죠.",
                    "바람이 환영을 흩었다. 어둠 속에서 날아든 비황신침도 그 바람에 빗나갔지만, 비류연은 그런 시도가 있었다는 것조차 몰랐다.",
                    "비류연|쳇! 역시 가짜였나? 그나마 진짜가 아니라서 다행이로군.",
                    "그때 동굴 저편에서 비명이 들렸다.",
                    "나예린|도와줘요! 비…… 비류여어어언!",
                    "옷자락에 몰래 이어 둔 뇌령사를 따라, 비류연이 그녀 곁에 닿았다.",
                    "비류연|나 소저, 괜찮아요? 무슨 일 있어요?",
                    "나예린|어떻게 절 찾았죠?",
                    "비류연|네, 감이요. 좋아하는 사람이 그 어떤 미로 안에 갇혀 있다고 해도 전 찾아낼 수 있어요. 그것이 바로 사랑의 힘이죠. 음하하하하!",
                    "나예린|그런데 비 공자도 환상은 아니겠죠?",
                    "비류연|이렇게 생생하고 싱싱한 환상 보셨나요, 나 소저?",
                    "나예린|그것도 그렇군요.",
                    "어둠 속에서 위지천이 이를 갈았다.",
                    "위지천|너만…… 죽으면……. 네놈만 이 세상에 없으면…… 저 미소를 내 것으로 만들 수 있어. 내 것으로…….",
                    "그의 손에서 염마뢰가 굴러 나갔다. 폭발과 연쇄 붕괴가 두 사람을 삼켰다. 학관은 그가 염마뢰를 던졌다는 사실을 알지 못했다.",
                } },
            { 20, new[] {
                    "열린 입에 꽂힌 섬뢰창이 묵린혈망을 쓰러뜨렸다.",
                    "비류연|쳇! 내단은 없나? 만일 내단이 있었으면 비싸게 팔 수 있었을 텐데…….",
                    "내단은 없었다. 이십육 일째, 놈의 마지막 몸부림이 출입구마저 막아 버렸음을 알았다.",
                    "매몰 사십사 일째. 비류연이 벽에 귀를 댔다.",
                    "비류연|얼래? 거참……. 너무 얇아요. 반대편에 공간이 있긴 한데, 아무래도 이 벽 뒤에 물이 있는 것 같아요. 여길 부수면 펑 하고 터질지 몰라요.",
                    "나예린|이미 한번 맡겼던 목숨. 다시 한 번 류연에게 맡기죠.",
                    "비류연|좋아요! 저당 잡으신 목숨! 반드시 돌려 드리죠. 두렵지는 않아요, 예린?",
                    "나예린|아뇨! 류연은요?",
                    "비류연|후후……. 어찌 된 영문인지 아직은 죽음이란 게 실감이 나지 않네요. 좀 질기거든요.",
                    "비류연|예린, 혹시 잊은 것 없어요? 다시 한 번 생사를 건 도전을 하기 전에 행운의 여신의 축복을 받고 싶은데 어떻게 생각하세요, 여신님?",
                    "나예린|그런 걸 꼭 해야 하나요? 안 하고 넘어가면 안 될까요?",
                    "비류연|불가! 절차란 꼭 지키라고 있는 거예요.",
                    "나예린|……좋아요!",
                    "나예린이 먼저 입을 맞췄다. 살짝, 그의 입술에. 그날이 마침 사십사 일째였다.",
                    "푸른 뇌전이 암벽에 작렬했다. 벽이 뚫리고 물살이 두 사람을 휩쓸었다. 수공에 약한 나예린이 정신을 잃자, 비류연은 그녀를 끌어안고 숨을 불어넣으며 파양호까지 헤엄쳐 나갔다.",
                    "강씨|글쎄, 정말이라니깐! 파양호에는 용이 살고 있어! 용과 선녀가 살고 있는 것을 내가 이 눈으로 똑똑히 봤다니깐!",
                    "천무학관에서는 빈 관 둘을 놓고 장례가 치러지고 있었다.",
                    "나백천|내 맹세컨대 그놈들을 이 세상에서 몰살시켜 버리고야 말겠네. 그리하여 그들의 피로 딸아이의 죽음에 조문하고자 하네!",
                    "장홍|류연! 자네같이 죽여도 죽여도 절대 죽을 것 같지 않던 사람이 이렇게 어처구니없이 죽다니…….",
                    "비류연|누구 장례식이에요?",
                    "장홍|자네 장례식!",
                    "비류연|어, 그래요? 조의금은 많이 거두었나요?",
                    "장홍|애석하게도 그리 많이 거둬들이지 못했네. 반면 나예린 소저 쪽은 난리도 아니라네. ……응?",
                    "관도|와아아아! 우와아아아!",
                    "나백천|오오! 예린아! 이것이 꿈은 아니겠지?",
                    "나예린|네! 아버님! 다녀왔습니다.",
                    "빙검|정말 잘 돌아오셨습니다. 다시 한 번 생환을 축하드립니다.",
                    "비류연|내가 안 죽고 살아와서 무척이나 아쉽죠?",
                    "사십사 일째의 최종 집계에서 사망자는 한 명도 없었다. 환마동 시험은 두 사람 모두 합격이었고, 후보 오십 명의 화산행이 결정되었다.",
                } },
            { 21, new[] {
                    "빙검|하북 십검의 일인이자 정의문의 장로이기도 한 당신이 어째서?",
                    "이송학|본래 난 성격이 원만해 패배를 당해도 별 느낌이 없을 줄 알았지요. 하지만 누군가에게 패하고 나서야 내가 얼마나 승부에 집착하는 나약한 인간인지 깨달았습니다.",
                    "빙검|그자가 누구였소이까?",
                    "이송학|부끄럽게도 그자는 한 소년이었습니다. 그것도 손 한 번 제대로 못 써 보고 당한 참담한 패배였습니다.",
                    "염도와 빙검의 심장이 뜨끔했다.",
                    "염도|(에이……, 설마 아니겠지. 아닐 거야…….)",
                    "염도와 빙검을 알아본 산적들 앞에서 노사들이 중재해 길이 열렸다. 일행은 흑랑채를 떠났다.",
                } },
            { 22, new[] {
                    "혈쇄의 비차륜이 그 주인에게로 되돌아갔다.",
                    "+비류연|돌려줄게요. 아까 빌린 거.",
                    "대홍산을 떠나기 전, 임덕성이 일행에게 한마디를 남겼다.",
                    "임덕성|아까 마지막에 무의 극의를 추구하는 데 출신 따위야 아무런 상관이 없지 않겠냐고 하더구나. 그러니 내 아들내미를 잘 부탁하오!",
                    "임성진|그럼 이만 가 보겠습니다. 건강하십시오.",
                    "임성진이 동료로 합류합니다. 파티 편성에서 출전할 동료를 선택할 수 있습니다.",
                } },
            { 23, new[] {
                    "은섬풍이 지사진을 갈랐다.",
                    "모사령|이…… 이런 바보 같은. 어, 어떻게 이런 일이……. 이런 일이…….",
                    "비류연|그럼 이로써 당신이 범한 죄가 다섯 개로 추가되었군요? 편안한 죽음은 보류해 두죠.",
                    "모사령은 죽이지 않고 붙잡아 두었다. 물어볼 것이 남아 있었다.",
                    "적혈|이대로는 피해가 너무 막심합니다. 후퇴해서 전력을 보존해야 합니다. 증거를 남기지 마라. 모두 지워 버려!",
                    "협곡을 막던 쇠사슬이 걷혀 갔다.",
                    "염도|어라? 이 녀석들이 갑자기 뭔 짓거리지? 왜 후퇴해? 아직 어느 한쪽도 전멸하지 않았는데? 근성 없는 녀석들!",
                    "빙검|저들이 지금 후퇴를 결정했다는 이야기일세!",
                    "빙검|……빚을 졌군. 그것도 아주 큰 빚 말이야.",
                } },
            { 24, new[] {
                    "매화가면|뭐냐? 너의 본신 실력이 겨우 이 정도에 불과했단 말이냐? 화산의 검이라는 게 이 정도까지 형편없는 것이었더냐?",
                    "윤준호|미천한 것은 저 개인의 책임입니다. 화산의 검을 모욕하지 마십시오. 화산의 검은 무한합니다.",
                    "매화 향기가 객잔을 가득 채웠다.",
                    "관도|저…… 저것은 검향지경!",
                    "붉은 검기가 복면인의 자색 무복을 너덜너덜하게 만들었다. 그러나 회심의 일격을 막아 낸 초식은 윤준호가 잊을 수 없는 것이었다. 매염토망. 윤준호가 검을 거두고 바닥에 엎드렸다.",
                    "윤준호|화산파 불초제자 윤준호! 삼가 태사부님을 배알합니다!",
                    "매화가면|고개를 들거라. ……많이 늘었구나.",
                    "윤준호|가…… 감사합니다, 태사부님!",
                    "매화가면|무…… 무슨 소리! 난 그저 단순한 의문의 복면인 매화가면일 뿐일세. 내 말뜻 알겠나?",
                    "윤준호|네! 태사부님!",
                    "매화가면|전혀 못 알아듣고 있잖나!",
                    "다음 날 태극의 인재에 관심을 보인 회색 장삼의 노인이 일행에 끼었다.",
                } },
            { 25, new[] {
                    "극안으로 버틴 모용휘의 몸에 상처는 쌓였다. 그 앞에 비류연이 섰다.",
                    "비류연|선수교체를 해도 될까요?",
                } },
            { 26, new[] {
                    "구출대는 빠져나왔다. 그제야 나예린이 비류연의 가슴을 보았다.",
                    "나예린|……류연! 피가…….",
                    "비류연|아아, 별거 아니에요. 조금 방심했나 봐요. 상처인가? 얼마 만인지……. 나의 성혈을 외출시킨 대가는 무척이나 비쌀걸!",
                    "비류연|전 교육을 너무 엄격하게 받아서 빚지는 걸 무척이나 싫어하거든요. 그런데 오늘은 갚아야 할 빚이 덜컥 생기고 말았네요. 후후후!",
                    "혈도를 짚어 피를 멎게 하는 수법을 보고 염도는 심점혈인가 짐작했다.",
                    "비류연|그녀는 너무 노출되었고, 적들의 저력 또한 무섭습니다. 지금 그곳보다 안전하고 합리적인 곳이 있을까요?",
                    "염도|그것은……, 지금 그녀를 천무봉으로 데려가자는 이야기?",
                    "새벽, 일행은 의식 없는 은설란을 데리고 묘시 점검을 향해 산을 올랐다. 그 앞에 빙검이 거대한 호랑이 한 마리를 내려놓았다.",
                    "빙검|별거 아니네!",
                    "비류연|수고하셨어요. 우리가 내려간 사이에 해 줄 일이 한 가지 있어요. 혹시나 필요해질지 모를 게 있거든요!",
                    "부탁받은 수색의 대상은 그 대호였다. 뒤에 화평장은 불타 없어졌고, 안명후의 철침과 함께 많은 흔적이 사라졌다.",
                } },
            { 27, new[] {
                    "비류연|좋아요, 아주 좋아요! 재미있는 놀이였어요. 그런데 더 보여 줄 것이 아직 남아 있나요?",
                    "도추운|발만 빠른 쥐새끼가 하늘 높은 줄 모르고 까부는구나!",
                    "종리추|이번에는 용케 피했다. 칭찬은 해 주마. 하지만 다음에도 피할 수 있을까?",
                    "비류연|상대의 기량을 읽는 것도 실력! 읽어 낸 기량을 제압하는 것 또한 실력! 승자는 어떤 경우에도 승자일 뿐이니깐.",
                    "은설란|대공자!",
                    "대공자 비|아란 소저…….",
                    "처음으로 대공자의 얼굴이 경악으로 흐트러졌다. 그가 먼저 확인한 것은 천살의 처치가 제대로 되었는지였다.",
                    "은설란|3년 만인가요?",
                    "대공자 비|정확히는 2년 10개월 만이오!",
                    "은설란|하지만 정말 놀랍군요, 당신이 직접 나서다니…….",
                    "대공자 비|한 번쯤 이런 대회에서 우승해 보는 것도 좋을 것 같다는 생각이 문득 들더군요.",
                    "은설란|그때는 그렇게 쾌활하고 명랑했었는데…….",
                    "대공자 비|이미 지나간 과거는 의미가 없소. ……자네의 이름은?",
                    "비류연|존성대명이겠지요. 비, 류, 연!",
                    "대공자 비|호오? 자네가……. 아니, 없네! 하지만 그 이름 기억해 두지!",
                    "비류연|그런데 댁의 이름은 뭐죠? 남의 이름을 알아갔으면 자신의 이름도 내놓아야 하는 게 예법 아닌가요?",
                    "추명|넌 아직 이분의 성함을 알 자격이 없다.",
                    "대공자 비|비류연이라고 했던가? 오늘은 은 소저를 봐서 이만 용서해 주겠다. 가자!",
                    "비류연|음, 근거 희박한 은혜를 받는 것은 좋아하지 않는데…….",
                    "뒤에 은설란이 일곱의 이름을 짚었다. 마천일걸 추명의 흑응익, 이걸 종리추의 칠련창, 삼걸 도추운의 사갈검편.",
                    "은설란|그는 자신의 승리에 대해 절대적인 자신감에 가득 차 있어요.",
                    "비류연|아, 별거 아니에요. 그런 것만 보면 부숴 버리고 싶은 충동이 일어서요.",
                    "사적 알현의 자리. 칠걸은 봉인을 풀 허락을 구했다.",
                    "대공자 비|아직은 너희들의 진정한 힘을 드러낼 때가 아니다. 조금만 더 기다려라. 곧 그때가 온다.",
                    "대공자 비|돌발적인 변수가 될 가능성을 품고 있는 요소는 사전에 미리 제거해야만 한다. 교옥! 그의 영혼을 사로잡아 그 안에 든 모든 것을 알아내라.",
                    "교옥|……명을 받들겠습니다.",
                    "개회식. 운영 총책임자 혁중이 단상에 섰다.",
                    "혁중|본인은 영광스럽게도 제10회 화산규약지회의 운영 총책임을 맡게 된 혁중이라고 하네. 그냥 혁 노야라고 불러 주었으면 좋겠네.",
                    "혁중|무공 겨룸은 너무나 극단적으로 사람들의 투쟁심을 자극할 수 있다는 것일세. 그래서 이번 대회에는 대삼원칙이 있네. 그것은 바로 우정과 화합, 그리고 평화일세.",
                    "참가자|그건 미친 짓이야! 그딴 게 가능할 리 없잖아!",
                    "혁중|자네들은 십인 일조로 수화목금토 다섯 개의 주제를 가진 관문에 도전하게 될 걸세. 원칙은 오직 하나, 오 대 오 반반이라는 것뿐이네.",
                    "남자는 태양관, 여자는 월음관. 흑도와 백도가 한방을 쓰는 숙소에서 불침번을 정하는 첫 밤이 시작됐다.",
                    "일주일 뒤, 조를 가를 추첨이 시작됐다.",
                } },
            { 28, new[] {
                    "검후|일단 이 자리에서 옮겨야겠군요. 응급조치를 취했지만 이대로는 안심할 수 없겠어요.",
                    "검성|그런 무지막지한 물건까지 써 가며 여기까지 필사적으로 도주해 왔다는 것이군. 아무래도 사태는 상상 이상으로 심각한 것인지도 모르겠군.",
                    "검후|그런데 누가 옮기죠?",
                    "임덕성|저……, 그 일 저희에게 맡겨 주시면 안 될까요?",
                    "도성|자넨 또 누군가?",
                    "임덕성|힘이라면 누구에게도 뒤지지 않습니다. 보시다시피 체력도 튼튼하고 말도 아주 잘 듣습니다.",
                    "모경|예? 제, 제가요?",
                    "임덕성|그럼 이 나이에 내가 하랴?",
                    "모경|제, 제가 하겠습니다.",
                    "검성|도대체 화산에서 지금 무슨 일이 일어나고 있는 거지…….",
                    "한편 금요관. 조원끼리 줄로 몸을 묶고 절벽을 오르는 시험이었다.",
                    "시험관|명심하십시오. 이 줄을 절대 자르면 안 됩니다. 줄이 끊어지면 그 즉시 그 조는 자동으로 탈락 처리됩니다.",
                    "절벽의 돌이 부서지고 노학의 줄이 잘렸다. 비류연은 자기 줄을 끊고 직지질주로 절벽을 내달렸다.",
                } },
            { 29, new[] {
                    "동굴에서 안명후가 깨어났다. 곁에는 교옥이 앉아 있었다.",
                    "교옥|아, 깨어나셨군요. 처음 뵙겠습니다. 제 이름은 교옥이라고 합니다.",
                    "안명후|화산은? 천무봉은 무사합니까? 그렇다면 사람을 불러 주십시오. 거대한 음모에 대한 것입니다. 화산이 위험합니다!",
                    "교옥|말 안 듣는 아이를 전 싫어하죠. 자, 제가 자장가를 불러 드릴게요. 장송곡이라는 이름의 영원한 꿈을 꿀 수 있도록 해 주는 자장가를.",
                    "교옥은 장송곡을 자장가라 부르며 안명후를 살해했다. 일행이 돌아왔을 때, 시신 옆에는 상처 하나 없이 기절한 교옥이 쓰러져 있었다.",
                    "대공자 비|이자를 이토록 잔인하게 살해한 자가 왜 교옥은 살려 두었을까? 그는 그녀가 죽으면 무척 곤란해지는 사람이라는 뜻이지.",
                    "대공자 비|각 조원 중 한 명이라도 낙오자가 발생하면 그 조는 실격 처리된다. 자네, 혹시 죽은 사람도 때때로 말을 할 수 있다는 사실을 알고 있는가?",
                    "죽은 이의 오른손에서 피 묻은 천율패가 나왔다. 새겨진 이름은 비류연이었다.",
                    "비류연|그 은가면들이 기절시켜 놓고 아무 패나 하나 뽑아 그 손에 쥐여 줬을 수도 있잖아?",
                    "대공자 비|아냐, 그건 틀리지. 자네는 그자들에게 당한 적이 없잖은가?",
                    "비류연|아무도 나를 믿지 않는다면 여기 있을 필요가 없겠지! 하지만 이 누명은 반드시 벗고야 말겠어!",
                    "앞을 막은 여섯은 쓰러졌을 뿐 아무도 죽지 않았다. 숲 어귀에서 기다리던 나예린이 그를 맞았다.",
                    "나예린|어딜 혼자 가려 그래요? 같이 가야죠. 혼자서 가면 못써요. 우린 동료잖아요.",
                    "장홍과 윤준호, 효룡, 이진설, 그리고 다른 조인 모용휘까지 풀숲에서 걸어 나왔다.",
                    "모용휘|우린 자네를 믿어! 그래서 자네를 따라가기로 했네.",
                    "장홍|어리석은 다수가 만드는 것을 주류라고 하는 게 아냐. 어느 게 옳은 방향이 될지는 역사가 정하지.",
                    "비류연|쳇, 이 몸을 이 지경까지 몰아넣다니……. 방심하다가 한 방 먹고 말았어! 일단 가장 의심 가는 놈들부터 족쳐 봐야지. 그 은가면들.",
                    "비류연|실을 하나 풀어 뒀거든! 그들이 어디 있든 그 실이 길잡이가 되어 나를 인도할 거야! 좋아! 그럼 친구들, 가 볼까!",
                } },
            { 30, new[] {
                    "검게 그을린 폐허의 한켠, 재를 뒤집어쓴 염도와 빙검이 나란히 서 있었다.",
                    "염도|한심하군, 정말 한심해. 나 자신이 이렇게 한심할 줄이야…….",
                    "빙검|그래, 맞네. 자네는 한심해.",
                    "염도|이 자식이, 뭐라……!",
                    "염도는 말을 삼켰다. 빙검이 으스러지게 쥔 주먹에서 핏방울이 떨어지고 있었다.",
                    "빙검|내 책임이야. 내가 무의미한 희생을 만들었어. 죽어 간 아이들을 볼 면목이 없군. 날 비웃어도 좋아, 염도. 이번만은 그것을 허락하지.",
                    "사망 세 명, 중상 열세 명, 경상 스물다섯 명. 셋이라 해서 그 생명의 무게가 줄어드는 것은 아니었다.",
                    "염도|이 바보 자식이! 그게 어떻게 자네 탓뿐인가? 인솔 노사는 자네 혼자만이 아니었어! 나도 인솔 노사였다구! 모든 걸 혼자서 짊어지려 하지 마! 나도 책임을 나눠 질 권리가 있다구!",
                    "+빙검|……고맙네.",
                    "염도|……뭐? 지금 뭐라고 했나? 고마? 뭐라고, 엉?",
                    "빙검|두 번은 말 안 해! 잊어버려. 환청이었으니깐!",
                    "빙검|그런 건 아무래도 좋네! 사부님이 예견하신 그때가 온 것 같아. 악몽의 부활이……. 두 개로 나뉘었던 거울이 다시 하나로 합쳐져야 할 때가 온 것 같네.",
                    "염도|건곤조화신경……. 사부님께서 남기신 마지막 비전.",
                    "빙검|그것을 계승할 자를 찾아야 하네.",
                    "염도|난 두 사람이 떠오르는군. 하나는 재수 없고, 하나는 듬직하고.",
                    "빙검|우연이군. 나도 마찬가지일세.",
                    "불탄 홍매곡을 바라보던 혁중에게 모용휘가 다가왔다.",
                    "혁중|이제 결심이 섰느냐? 좋은 얼굴이다. 방황은 끝났느냐?",
                    "모용휘|예, 어르신! 제가 가야 할 길을 찾았습니다. 어떻게 해서든 이기고 싶은 두 사람이 있습니다.",
                    "모용휘|하나는 어떻게 해서든 이기고 싶은 친구고, 다른 한 사람은 반드시 이겨야만 하는 적입니다. 저는 그자를 용서할 수 없습니다.",
                    "혁중|좋아, 앞으로 각오해야 할 거다. 일단 전설로 남은 무공이니깐, 쉽지 않을 거야.",
                    "홍매곡을 빠져나간 곳에서, 독고령이 외눈을 번뜩이며 비를 노려보았다.",
                    "독고령|왜 날 구했죠?",
                    "대공자 비|그냥 단순한 변덕이오.",
                    "독고령|난 당신을 증오해요!",
                    "대공자 비|그건 당연하오. 당신은 날 증오할 자격이 충분하오.",
                    "독고령|여…… 역시 당신은…… 그 사람이 맞군요. 그때 나를 한 번 죽였으면서, 왜 이번에는 살린 거죠?",
                    "대공자 비|나도 모르겠소. 하지만 한 가지 확실한 건 그때의 죄책감 때문은 아니라는 것이오.",
                    "대공자 비|당신을 지금 당장은 돌려보내 줄 수가 없소. 아직 나에게는 해야 할 일이 남아 있기 때문이오.",
                    "독고령|당신을 반드시 죽이고야 말겠어요!",
                    "대공자 비|언제라도 가능하다면 시도해도 좋소!",
                    "대공자 비, 한때 은명이라 불렸던 남자의 대답이었다.",
                    "나예린|아무것도 남지 않았군요. 여기서 다시 화산규약지회가 열릴 수 있을까요, 류연?",
                    "비류연|걱정 말아요. 그 비란 녀석이 한마디만은 옳은 소리를 했으니깐요. 불사조는 재 속에서 되살아난다!",
                    "비류연|아직 끝나지 않았어요. 이제 시작이죠. 이런 짓을 한 놈들은 그 대가를 치르게 될 거예요. 빚지고는 찜찜해서 잠을 못 자죠.",
                    "나예린|그렇군요. 빚을 지고 그냥 있으면 안 되겠죠. 백 배로 되갚아 주지 않으면!",
                    "비류연|아뇨! 만 배예요! 이자는 복리에 복리에 복리가 붙어서 비싸다구요!",
                    "같은 무렵, 청룡은장이 불타고 있었다. 백염백발의 노인이 쓸모없어진 연금 증서를 쥔 채 그 앞에 서 있었다.",
                    "노인|어…… 어떻게 이런 일이…….",
                    "노인|다시 그 녀석을 찾아봐야 하나……. 오랜만에 강호 나들이나 한번 할까…….",
                    "노인은 증서를 불꽃 속에 던지고 새로운 목적지를 향해 한 발짝 내디뎠다.",
                } },
            { 31, new[] {
                    "청룡검이 파편으로 터졌다. 살룡의 삼현조화 도막을 뚫은 파편이 팔과 뺨에 흔적을 남겼고, 벗겨진 복면 아래 얼굴이 드러났다.",
                    "유재룡|이정, 자, 자네가……, 어떻게……? 은장과 표국은 떨어질래야 떨어질 수 없는 붕우지간인 것을…….",
                    "살룡|배신이라니? 남이 들으면 오해할 말 같은 건 하지 말아 주게. 자네와 사귈 때부터 나의 목적은 열쇠의 행방을 찾는 것이었네.",
                    "유재룡|퉤엣! 네놈은 영원히 그것을 손에 넣지 못할 것이다! ……살아라…….",
                    "살룡|자네와 지냈던 십 년, 무척이나 즐거웠다네.",
                    "유재룡은 그 손에 죽었다.",
                    "남매는 그 말을 듣지 못했다. 불타는 은장에 백발 노인 하나가 걸어 들어왔다.",
                    "노사부|여기가 청룡은장이 맞나? 난 저곳의 고객이니 그 안의 은에서 내 몫만큼 가져갈 권리가 있는 것 같은데 말야.",
                    "살룡대원|저기……, 송구스럽지만 저 안에는 지금 단 한 푼의 은도 황금도 없습니다.",
                    "노사부|뭐? 없다고? ……하지만 이 일을 어쩐다. 이대론 밀린 외상 술값도 못 갚는데……. 다시 그 녀석을 찾아야 하나……. 오랜만에 강호 나들이나 한번 해 볼까.",
                    "철화장의 월산이 비류연이라는 이름과 검을 알려 주었다. 노인은 중양표국을 찾았다.",
                    "장우양|어서 오십시오. 중양표국이라는 작은 표국을 맡고 있는 장우양입니다.",
                    "노사부|난 이름과는 인연이 없는 사람이네. 그냥 늙은 사부, 노사부라고 부르게. 한 녀석을 찾고 있네. 그 망할 녀석 이름은 비류연이라고 하네. 내 못난 말썽꾸러기 제자 녀석일세.",
                    "장우양|제가 몇 년 전에 파양호 근방까지 데려다 준 적이 있습니다.",
                    "노사부|저 표행은 어디로 향하는 건가?",
                    "장우양|나……, 남창입니다.",
                    "천무학관과의 첫 거래를 싣고 남창으로 가는 표행. 산적이 한 번도 나오지 않았다.",
                    "장우양|역시 그렇지? 벌써 세 번째로군. 아무 일도 없는 게 말일세.",
                    "혈표|아이들을 내놓아라!",
                    "장우양|아이들? 우리 중양표국은 목록에 기재된 물품 이외의 것을 비합법적으로 운송하지 않소이다.",
                    "장우양|일개 표국이라니! 말조심해라! 장담하건대 삼 년 안에 우리 중양표국은 업계 일위인 중원표국을 제치고 진정한 강호제일표국으로 거듭날 것이다!",
                    "검을 뽑으려던 호위들보다 먼저, 하얀 질풍이 수풀의 매복을 지웠다.",
                    "혈표는 백호에게 죽었다. 유란·유운비가 실전 승리를 거둔 것이 아니었다.",
                    "장우양|이게 어찌 된 일인가?",
                    "진소령|유 대협, 보셨나요?",
                    "유은성|하얀 형제만 잠깐 확인했을 뿐입니다.",
                    "팔섬풍 여덟 마리 뒤에 황금 눈의 백무후가 나타났다.",
                    "노사부|요 녀석, 하양아! 인사 온 거냐? 그런데 다 함께 가기에는 머릿수가 너무 많구나.",
                    "여덟은 돌려보내고 한 마리만 말들을 놀라게 하지 않도록 뒤를 따랐다.",
                    "식량 수레에 숨어 있던 남매가 나왔다. 장우양은 살아남은 아이들을 보호하기로 했다. 한 달 뒤 표행은 남창에 닿았다.",
                } },
            { 32, new[] {
                    "남궁상은 이기어검을 몸으로 겪었다. 그래도 아직 비상련화를 막은 것은 아니었다. 승부는 보름 뒤였다.",
                    "나예린도 사부에게 비설보를 청했다. 사저를 구할 날을 위해 적공을 쌓기 위해서였다.",
                    "비천은 시험 뒤 더 자격 있는 이에게 주기로 진소령이 맡았다.",
                    "진소령|당분간 이 검은 제가 보관하고 있겠습니다. 두 사람 모두 이 검에 어울리는 사람이 되도록 정진하거라.",
                    "학관의 시험은 시작됐고 표행도 남창에 닿았다. 같은 도시에 모인 비류연과 사부는 아직 서로를 만나지 않았다.",
                } },
            { 33, new[] {
                    "밤의 결판은 어둠 너머로 감춰졌다.",
                    "중양표국. 숨어 지내던 아이들이 오빠를 졸랐다.",
                    "동생|오빠~ 경영이 오빠~ 우리 시장에 놀러 가자! 그날 이후로 한 번도 안 나갔잖아!",
                    "유경영|안 돼! 지금은 이곳에 있어야 안전해!",
                    "그때 유은성이 달려왔다. 비무 상대 남궁상이 피살당했다는 소식이었다.",
                } },
            { 34, new[] {
                    "이시건|왜! 왜! 왜! 통하지 않는 거냐! ……내가……, 내가……, 졌단 말인가?",
                    "섬광탄이 터졌다. 이시건과 윤이정이 달아나며, 효룡을 향해 한마디를 던졌다.",
                    "효룡|당신 같은 사람은 내 사형이 아니오.",
                    "이시건|거, 겁쟁이? 누구더러 감히 겁쟁이 도망자라는 거냐! 이번엔 그냥 물러나 준 것뿐이야.",
                    "효룡|다음을 기약하는 사람치고 제대로 된 사람 못 봤소.",
                    "나예린의 검은 두 사람에게 흔적을 남겼지만 증인을 붙잡지는 못했다.",
                    "감옥. 나예린이 철창 앞에 섰다.",
                    "나예린|그 사람, 사로잡으려 했는데…….",
                    "비류연|그럼 성공이네요. 예린이 직접 움직였잖아요, 몸소.",
                    "감옥에서 실패했다 말하자 비류연은 스스로 움직였으니 성공이라 답했다.",
                    "비류연|괜찮아요. 나에게 이보다 더 반가운 소식은 없으니까. 그래요? 그럼 잘됐네요. 오직 예린만이 해 줄 수 있는 일이 하나 있거든요. ……사식! 예린이 손수 만든 음식을 먹고 싶어요.",
                    "나예린|사실 한 번도 해 본 적이…….",
                    "비류연|괜찮아요. 누구든 뭔가를 하려면 처음이란 걸 겪어야 하잖아요? 예린은 이미 용기를 갖추고 있으니 문제없어요. 내가 보증할게요.",
                    "다음 밤, 중양표국의 담을 넘던 두 그림자가 있었다.",
                    "유은성|자자, 가만히 있게. 난 담이 작아서 사소한 일에도 깜짝깜짝 잘 놀라거든.",
                    "진소령|검은 집어넣어라.",
                    "두건을 벗자 죽은 줄 알았던 남궁상과, 공손절휘가 있었다. 거짓 죽음의 전모가 드러났다.",
                    "유은성|잠깐! 그럼 최근에 일어난 입관 후보생 연쇄 살인 사건은 자네의 소행이 아닌가?",
                    "공손절휘는 모용휘를 이기려 완장만 노린 습격자였고 사람을 죽인 적이 없었다.",
                    "남궁상|책략이라 해 주게. 유, 인, 책!",
                } },
            { 35, new[] {
                    "관제묘에 닿은 진소령은 영문을 몰랐다.",
                    "진소령|서찰이라니요? 전 서찰을 보낸 적이 없는데요?",
                    "같은 시각, 남매의 방에 숙부가 들어왔다.",
                    "윤이정|안심하거라. 이 숙부가 왔단다. 여긴 너희들에게 너무 위험하다. 그러니 어서 나랑 가자꾸나.",
                    "유경영은 윤이정 오른팔의 용린폭 상처를 알아봤다. 아버지가 일러 준 가문 비전이 원수의 몸에 남아 있었다.",
                    "유경영|저자는……, 아버님의……, 아버님의…….",
                    "윤이정|흐흐흐, 애비를 닮지 않아 몇 배나 똑똑한 녀석이구나. 하지만 이걸 어쩌지? 이 방 주위에는 내가 쳐 놓은 차음막 때문에 소리가 밖으로 새어 나가지 않는다는 것을?",
                    "검을 든 어른 앞에서 소년은 선아를 감쌌다.",
                    "백무후가 문을 부수고 윤이정을 찢어 던졌다. 나무를 방패로 세운 이시건도 왼쪽 얼굴을 크게 다쳤다.",
                    "이시건|내, 내 얼굴이……, 내 잘생긴 얼굴이…….",
                    "이시건은 남은 십삼혈과 빈사의 윤이정까지 던져 시간을 벌었다. 노인이 던진 목침이 백무후의 콧등에 맞은 틈에 그 혼자 달아났다. 십삼혈은 전멸했고 윤이정의 최종 생사는 남았다.",
                    "전설이 될 포효가 남창에 울렸다. 감옥의 비류연도 익숙한 소리에 눈을 떴다.",
                    "진소령|과연 아미산의 주인이라 불릴 만한 신위군요. 우리 인간은 좀 더 자연 앞에서 겸손해질 필요가 있겠어요.",
                    "유은성|저도 설마 중원표국의 대표두이자 금강십이벽의 한 사람이 그런 파렴치한일 줄은 꿈에도 상상치 못했습니다, 진 소저.",
                    "유은성은 노인을 깨우러 들어갔다가 날아온 목침에 맞아 기절했다. 아이들은 돌아온 진소령의 품에서 진정했다.",
                    "진소령|천무학관의 현 관주이신 마진가, 마 대협이지. 그분이 전에 내 은사님이셨단다.",
                } },
            { 36, new[] {
                    "날아간 섬뢰가 처음으로 남궁상의 뜻을 따라 진소령의 목덜미 뒤에서 멈췄다.",
                    "진소령|어떻게……, 이런 일이……. 직접 가르치셨단 말씀이신가요?",
                    "빙검|여덟 개의 어검분영을 만들어 내는 그대의 높은 경지에는 한없이 미치지 못하는 수준이지만……, 그렇소이다. 가능성을 체현할 수 있는 몸을 만드는 데 우리는 주력했단 것이오.",
                    "진소령|저 자신을 과신하다니……. 산속에 틀어박혀 있던 사이에 하늘 위에 또 다른 하늘이 있다는 것을 잠시 잊고 있었군요. ……당신의 승리예요, 상!",
                    "남궁상|가, 감사합니다, 고모님!",
                    "승천무제 본선. 준호는 유운비를, 나예린은 유란을, 모용휘는 공손절휘를 합격시켰다.",
                    "모용휘|칠절신검 모용휘입니다!",
                    "검은 우산을 든 현의여인이 남궁상의 열 초를 피하고 합격했다. 그 신원은 아직 설명되지 않았다.",
                    "같은 무렵 동정호 자죽도. 몽무·환무를 데리고 온 영령이 마천각 입관을 청했다.",
                    "비류연은 사절단 명단에서 빠진 뒤 상자를 꺼냈다.",
                    "비류연|쓸 일이 없을 줄 알았는데…….",
                    "이진설|아쉽겠어요, 예린 언니.",
                    "사절단이 떠나는 아침, 삼성은 망루에서 배웅했다.",
                    "검성|돌아가서 아직 미완성인 바다 가르기나 완성해야겠네.",
                    "검후|저도 천 마리를 이천 마리로 늘릴 방도를 찾아봐야겠네요.",
                    "검후|저 아이들은 이제 밝은 곳에서 어두운 곳을 보러 가는군요.",
                    "길 위에서 묵빛 우산을 든 현의여인이 나예린 앞에 섰다. 마음을 읽을 수 없는 눈이었다.",
                    "현의여인|오랜만이에요, 린! ……이런, 너무 섭섭한데요. 설마 잊어버린 거예요, 린?",
                    "나예린|그, 그럴 리가……. 어떻게 내가 잊을 수 있겠어요, 내 생명의 은인을…….",
                    "나예린|연비!",
                    "현의여인|다시 한 번……, 오랜만이에요, 린! 십 년 만이군요.",
                } },
            { 37, new[] {
                    "관통한 뒤에도 백교는 살아 있었다. 독니가 등을 긁자 연비가 쓰러졌다.",
                    "린|여, 연비! 괜찮아요? 미안해요, 내가 돌아가기 싫어해서 모두들…….",
                    "연비|백응을 구하려고 그런 거였잖아요. 그럼 잘 부탁해요. 믿고 맡길 사람은 린밖에 없어요. 이 아이가 엄마나 아빠 백응처럼 자라서 멋지게 하늘을 가르는 모습을…….",
                    "린에게 달려든 백교를 끝낸 사람은 손을 한 번 턴 노사부였다.",
                    "노사부|정신 차려라, 이 녀석아! 이 버릇없는 놈, 허락도 없이 맘대로 죽을 셈이냐! 네놈이 없으면 누가 날 먹여 살리냐?",
                    "연비|우리의 악연은……, 역시 저승까지였던 건가요.",
                    "노사부|시끄럽다! 네 녀석이 내 허락도 없이 죽을 수 있을 것 같으냐? 헹, 어림도 없지. ……독과 해독제는 가까운 법.",
                    "사흘 밤낮 달인 약으로 연비는 살아났다.",
                    "노사부|감사나 하고 있어라. 생명의 빚이 얼마나 큰지는 네놈도 모르진 않겠지?",
                    "현재 · 배 안. 나예린은 오랜 꿈에서 깨어 연비에게 그날을 이야기했다.",
                    "나예린|그땐 정말로 연비가 죽는 줄 알았어요. 그 손짓 한 번에 백교가 그대로 절명했어요. 정말 대단한 분이었어요.",
                    "연비|그건……, 밝히는 걸 따로 허락받지 못해서요. 건강이라면야, 아마 죽여도 죽지 않을 정도로 정정할걸요?",
                    "은인의 마음만은 여전히 읽을 수 없었다. 그믐밤의 동정호가 다가오고 있었다.",
                } },
            { 38, new[] {
                    "마하령이 붕결 일도광 태산봉으로 이겼다. 용천명에게 아름답다는 말을 들은 뒤 그녀는 결승을 기권했다.",
                    "용천명|그럴 리가 있겠소? 난 진심이오.",
                    "남궁상이 임시 대장이 됐다.",
                    "다음 날 백응이 돌아왔다. 독고령을 아직 찾지 못했다는 소식이었다.",
                    "같은 무렵 천무학관. 노사부가 정원의 동상 앞에 섰다.",
                    "노사부|이 동상은 도대체 누구 동상인가? ……여기서 그 녀석을 직접 본 놈은 한 놈도 없는 게냐?",
                    "노사부|저런 거짓 우상 따위는 차라리 녹여서 세숫대야로 쓰는 게 나아!",
                    "노사부는 혁월린 동상을 걷어찼고, 달려든 검존의 검끝을 한 손으로 붙잡았다.",
                    "노사부|그래, 그 망할 녀석은 지금 어디 있나?",
                    "마진가|아마도……, 마천각입니다.",
                    "검존|누구도 내 몸에 손대지 마라!",
                    "노인이 떠난 뒤 마진가는 특수 추적부대 무영각을 움직였다.",
                    "마천각의 밤. 사천왕이 신고식을 의논했다.",
                    "사천왕|좋다. 신고식은 치르게 해야지. 난 찬성이다.",
                    "은설란|그냥 조심하세요. 무조건 조심하세요. 이건 친구로서의 충고예요.",
                    "꽃잎과 함께 한 사내가 나타났다.",
                    "자군|이런이런! 아무리 기다려도 나의 이름을 물어 주는 이가 아무도 없으니, 이 얼마나 슬픈 일인가! 이에 나 미폭공자 자군은 그대들 백도의 꽃을 진심으로, 진심으로 열렬히 환영하오!",
